H('414.d.4.A',3,"Sensemaking helps a team assign the person who is best at stress analysis to the:","structures tasks",["catering","parking","marketing"],"Match skills to tasks.")
H('414.d.4.A',4,"A team that notices a member is overloaded and shifts work to others is practicing:","sensemaking within the team",["avoidance","conflict","delay"],"Awareness balances workload.")
