H('414.d.4.F',4,"Giving feedback to another team across a table works best when the comments are:","clear and about the work product",["personal","rushed","off topic"],"Focus on the product.")
H('414.d.4.G',3,"A team gets ten critique comments and decides which ones to act on by comparing each with the:","project requirements and goals",["author's mood","weather","day of the week"],"Evaluate comments against goals.")
H('414.d.4.G',4,"If a critique comment is unclear, the team should:","ask the reviewer to clarify",["ignore everything","assume the worst","delete the comment"],"Clarify before acting.")
H('414.d.4.H',3,"A design review presentation for a propulsion subsystem should show the current design, risks, and:","open questions for reviewers",["jokes","lunch plans","secret data"],"Reviews seek input.")
H('414.d.4.H',4,"A good design review slide uses a clear figure and brief text so reviewers can quickly see the:","key decision to be reviewed",["author's photo","slide background","cover art"],"Clarity helps reviewers.")
H('414.d.5.A',3,"A reverse engineering form for a small turbine records the parts, materials, and:","how they are assembled",["owner's name","shipping color","purchase price"],"Forms capture disassembly details.")
H('414.d.5.A',4,"An executive summary for a flight-test report should state the objective, the main result, and the:","recommendation",["lunch menu","team mascot","parking rule"],"Summaries give the key takeaways.")
H('414.d.5.B',3,"The best format for showing a mission profile of altitude over time is a:","graph",["paragraph","poem","contract"],"Graphs show trends.")
H('414.d.5.B',4,"The best format for listing component masses and totals is a:","table",["photo","story","cartoon"],"Tables organize numbers.")
H('414.d.5.C',3,"A report on a wind-tunnel test should present the setup before the:","results",["title","cover","index"],"Setup comes before results.")
H('414.d.5.C',4,"Sequencing a report from requirements to design to test helps the reader see how the design:","satisfies the requirements",["looks","costs","smells"],"Structure supports the argument.")
H('414.d.5.D',3,"Written steps for assembling a model rocket should be tested by a person who has not:","built it before",["seen a rocket","read a manual","used a tool"],"A fresh reader finds gaps.")
H('414.d.5.D',4,"A user manual for a drone should include safety warnings before the steps that involve:","spinning propellers",["decorating","naming","unpacking"],"Hazards must be flagged before the task.")
H('414.d.5.E',3,"The final design report for an aircraft concept should state the mission it was designed for and whether the design:","meets the mission requirements",["is pretty","is cheap to ship","is famous"],"Reports show results against goals.")
H('414.d.5.E',4,"Including a lessons-learned section in a final report helps future teams to:","avoid repeating mistakes",["ignore results","copy errors","skip planning"],"Lessons carry forward.")
H('414.d.6.A',3,"A mission requires an aircraft to carry 500 kg of payload to an altitude of 5,000 m. These are examples of:","mission requirements",["paint choices","team names","budget lines only"],"Altitude and payload define the mission.")
