H('414.d.15.D',4,"A GPS receiver needs signals from at least four satellites to compute a three-dimensional position and the receiver's:","clock error",["color","name","mass"],"The fourth satellite corrects the clock.")
H('415.d.1.A',3,"A civil engineering firm starts a bridge replacement by first writing a clear statement of the:","problem to be solved",["firm's logo","contractor's lunch","cost of paint"],"A clear problem definition guides the work.")
H('415.d.1.A',4,"Defining the problem for a flood-control project early helps the team avoid designing a solution for the wrong:","need",["color","name","mascot"],"The right problem leads to the right design.")
H('415.d.1.B',3,"Before designing a culvert, an engineer researches rainfall records and:","existing drainage conditions",["fashion trends","team songs","lunch menus"],"Research informs design.")
H('415.d.1.B',4,"Studying how similar retaining walls have performed over time is part of the:","research stage",["testing stage","marketing stage","closing stage"],"Past performance informs new designs.")
H('415.d.1.C',3,"Ideation for a city park drainage problem involves listing many possible:","solutions",["rules","penalties","deadlines"],"Ideation produces options.")
H('415.d.1.C',4,"Conceptualization turns a drainage idea, like a rain garden, into a rough design that can be:","compared with other concepts",["forgotten","planted at once","painted"],"Concepts are early designs.")
H('415.d.1.D',3,"A team chooses between three bridge concepts by scoring each against cost, safety, and:","constructability",["color","mascot","slogan"],"Criteria drive selection.")
H('415.d.1.D',4,"Selecting a concept for detailed development means choosing the option that best satisfies the project:","requirements",["jokes","moods","fashions"],"Requirements guide selection.")
H('415.d.1.E',3,"A site plan that shows buildings and roads at an exact scale is a:","technical drawing",["cartoon","poem","diary"],"Technical drawings use scale and standards.")
H('415.d.1.E',4,"A small physical model of a dam spillway used to see how water flows is a:","scale model",["contract","budget","permit"],"Models test concepts.")
H('415.d.1.F',3,"To test the strength of a new concrete mix, a lab breaks several cylinders and records the:","load at failure",["color","price","name"],"Tests give data.")
