H('415.d.1.G',4,"Design is iterative in civil projects because new site information often requires revisiting earlier:","design decisions",["accidents","lunches","bills"],"New data prompts revisions.")
H('415.d.1.H',3,"Presenting a stormwater design to a city council requires communicating clearly in drawings and:","plain language",["jargon only","jokes","silence"],"Clear communication supports approval.")
H('415.d.1.H',4,"Effective communication of a civil design helps ensure the contractor builds what the engineer:","intended",["forgot","ignored","hid"],"Clear documents prevent errors.")
H('415.d.2.A',3,"A civil project manager keeps a long project on time by setting interim deadlines and ranking tasks by:","priority",["color","size of font","author"],"Priorities guide the schedule.")
H('415.d.2.A',4,"Doing a task that other tasks depend on first helps prevent:","delays downstream",["good progress","early finish","rework"],"Dependencies drive priority.")
H('415.d.2.B',3,"For a highway project, a limit on available right-of-way is a:","constraint",["feature","bonus","hobby"],"Constraints bound the design.")
H('415.d.2.B',4,"Planning around a seasonal weather constraint, such as winter, means scheduling concrete placement for:","favorable conditions",["any time","only at night","freezing days"],"Constraints shape the schedule.")
H('415.d.2.C',3,"The completion of a foundation is a project:","milestone",["mistake","complaint","hobby"],"Milestones mark progress.")
H('415.d.2.C',4,"Dividing a large project into stages with deliverables helps managers see problems:","earlier",["later","never","only at the end"],"Stages enable tracking.")
H('415.d.2.D',3,"An email to a surveyor asking for a quick elevation check is an example of:","informal written communication",["a legal contract","a formal report","a permit"],"Different types suit different needs.")
H('415.d.2.D',4,"Stamped engineering drawings issued to a contractor are an example of:","formal communication",["casual chat","rumor","guess"],"Formal documents carry authority.")
H('415.d.2.E',3,"When a site plan does not fit the property, a good problem-solving strategy is to break the problem into:","smaller pieces",["bigger problems","rumors","jokes"],"Decomposition simplifies problems.")
H('415.d.2.E',4,"Problem solving on a construction team works best when members describe the problem and propose:","tested alternatives",["blame","excuses","delays"],"Collaboration finds solutions.")
H('415.d.3.A',3,"Under workplace safety laws, employers are responsible for providing a workplace that is free of:","recognized hazards",["coworkers","paperwork","schedules"],"Employers must protect workers.")
H('415.d.3.A',4,"Workers have a responsibility to follow safety rules and to report:","unsafe conditions",["lunch breaks","good weather","coworker names"],"Safety is shared.")
H('415.d.3.B',3,"OSHA stands for the Occupational Safety and Health:","Administration",["Association","Agency of Texas","Alliance"],"OSHA is the federal agency.")
H('415.d.3.B',4,"OSHA standards are important because they set minimum requirements to protect workers from:","workplace hazards",["paying taxes","taking breaks","being hired"],"Standards reduce injuries.")
H('415.d.3.C',3,"Industrial hygiene focuses on recognizing, evaluating, and controlling workplace:","health hazards like dust and noise",["office layouts","paint choices","staff lunches"],"Industrial hygiene protects health.")
H('415.d.3.C',4,"Measuring dust levels on a demolition site is an industrial hygiene activity that helps protect workers' long-term:","health",["wages","hours","vacations"],"Exposure monitoring protects health.")
H('415.d.3.D',3,"Hard hats, safety glasses, and gloves are examples of:","personal protective equipment",["engineering controls only","work rules","signage only"],"PPE protects the wearer.")
H('415.d.3.D',4,"Respirators are needed on a site when airborne contaminants cannot be:","controlled by other means",["seen","smelled","named"],"PPE is the last line of defense.")
H('415.d.3.E',3,"Slippery, uneven, or cluttered floors create a risk of:","slips, trips, and falls",["fires only","gas leaks","noise"],"Surfaces must be safe.")
H('415.d.3.E',4,"Guardrails or fall protection are needed when working at heights because falls are a leading cause of:","construction deaths",["good weather","delays only","paperwork"],"Fall protection saves lives.")

H('415.d.3.F',3,"Using a damaged extension cord on a job site creates a risk of:","electric shock",["sunburn","noise","tripping only"],"Damaged cords are shock hazards.")
H('415.d.3.F',4,"Digging near buried power lines without locating them first risks:","electrocution",["sunburn","boredom","noise only"],"Utility locates prevent contact.")
H('415.d.3.G',3,"A safety data sheet for a chemical includes information on its hazards and:","safe handling and storage",["price","color","advertising"],"SDSs guide safe use.")
H('415.d.3.G',4,"Flammable liquids should be stored in approved containers away from:","ignition sources",["shade","workers' lunches","tools"],"Separation prevents fires.")
H('415.d.3.H',3,"Posted exit routes and a map of emergency equipment are examples of workplace:","safety resources",["decorations","advertising","games"],"Resources help in emergencies.")
H('415.d.3.H',4,"A workplace emergency plan helps workers know where to go and whom to:","contact",["blame","avoid","ignore"],"Plans guide response.")
H('415.d.3.I',3,"Management leadership, worker participation, and hazard identification are elements of a:","safety and health program",["marketing plan","payroll process","uniform policy"],"Programs organize safety efforts.")
H('415.d.3.I',4,"Including workers in safety planning improves a safety program because workers know the:","hazards of their daily tasks",["office color","company logo","vendor list"],"Worker input improves programs.")
H('415.d.3.J',3,"A written emergency action plan describes how to report emergencies and how to:","evacuate",["advertise","paint","hire"],"Plans give clear steps.")
H('415.d.3.J',4,"Written plans and regular drills are important because people act more safely in an emergency when they have:","practiced the plan",["never heard of it","ignored it","forgotten it"],"Practice improves response.")
H('415.d.3.K',3,"A hazard communication program requires labels, safety data sheets, and worker:","training",["bonuses","vacations","uniforms"],"Programs inform workers about chemicals.")
H('415.d.3.K',4,"A container label that shows a flame pictogram warns workers that the contents are:","flammable",["edible","cold","heavy"],"Pictograms communicate hazards.")
H('415.d.3.L',3,"Workers must receive training on the hazards of their jobs and how to:","protect themselves",["avoid work","hide errors","skip breaks"],"Training prevents injuries.")
H('415.d.3.L',4,"Training for a new employee on a construction site should happen before the worker is exposed to the:","hazards",["paperwork","coffee","office"],"Training must come first.")
H('415.d.4.A',3,"To become a licensed professional engineer, a candidate typically first passes the Fundamentals of Engineering exam and becomes an:","engineer in training",["inspector","contractor","surveyor only"],"EIT is the first step.")
H('415.d.4.A',4,"After gaining required experience, an engineer in training may take the Principles and Practice exam to earn a:","professional engineer license",["driver's license","pilot license","trade permit"],"The PE exam follows experience.")
H('415.d.4.B',3,"Civil engineering careers include structural engineer, transportation engineer, and:","geotechnical engineer",["pastry chef","poet","DJ"],"Geotechnical engineers study soil.")
H('415.d.4.B',4,"An engineer who designs highways and traffic signals works in the sub-discipline of:","transportation engineering",["aerospace engineering","chemical engineering","electrical engineering only"],"Transportation engineers design roads.")

H('415.d.4.C',3,"A professional credential in engineering shows that a person has met standards of:","education, experience, and examination",["popularity","wealth","luck"],"Credentials show qualification.")
H('415.d.4.C',4,"Many states require continuing education to keep a professional engineering license:","current",["secret","cheap","blank"],"Licenses must be renewed.")
H('415.d.4.D',3,"Hydrology, flood control, and reservoir design belong to the civil sub-discipline concerned with the movement and control of:","water",["music","electricity only","traffic only"],"Water resources covers flow and storage.")
H('415.d.4.D',4,"An engineer who designs foundations and studies soil behavior is a:","geotechnical engineer",["transportation engineer","structural painter","electrical engineer"],"Geotechnical engineers focus on soil.")
H('415.d.5.A',3,"The mean of the data set 4, 6, 8, 10, 12 is:","8",["6","10","40"],"Sum 40 divided by 5 = 8.")
