H('415.d.8.A',3,"A civil project begins with conception, followed by scope definition, proposal, and:","contracting",["forgetting","retiring","hiding"],"Phases follow a sequence.")
H('415.d.8.A',4,"Writing the scope of a project defines what work is included and what is:","excluded",["colored","named","painted"],"Scope sets boundaries.")

